response:
[
  {
    "id": 1,
    "source": "<font color=\"#00FFFF\">Ihr könnt euch</font>\n<font color=\"#00FFFF\">nicht übers Gesetz erheben,</font>",
    "text": "<font color=\"#00FFFF\">شما نمی‌تونید</font>\n<font color=\"#00FFFF\">خودتون رو بالاتر از قانون ببینید</font>"
  },
  {
    "id": 2,
    "source": "<font color=\"#00FFFF\">weil ihr denkt,</font>\n<font color=\"#00FFFF\">nur eure Meinung ist richtig.</font>",
    "text": "<font color=\"#00FFFF\">چون فکر می‌کنید</font>\n<font color=\"#00FFFF\">فقط نظر خودتون درسته</font>"
  },
  {
    "id": 3,
    "source": "<font color=\"#FFFFFF\">Die wollen den Schönefelder Forst...</font>\n<font color=\"#FFFFFF\">- Da haben Sie recht.</font>",
    "text": "<font color=\"#FFFFFF\">اینا می‌خوان جنگل شونه‌فلد رو...</font>\n<font color=\"#FFFFFF\">- حق با شماست</font>"
  },
  {
    "id": 4,
    "source": "<font color=\"#FFFFFF\">Entschuldigung.</font>\n<font color=\"#00FF00\">Was ist denn hier los?</font>",
    "text": "<font color=\"#FFFFFF\">ببخشید</font>\n<font color=\"#00FF00\">اینجا چه خبره؟</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#00FF00\">Ist was passiert?</font>\n<font color=\"#FFFFFF\">Sachbeschädigung.</font>",
    "text": "<font color=\"#00FF00\">اتفاقی افتاده؟</font>\n<font color=\"#FFFFFF\">تخریب اموال عمومی</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#FFFFFF\">Verdacht auf Paragraf 86 StGB,</font>\n<font color=\"#FFFFFF\">Verbreitung von Propagandamitteln</font>",
    "text": "<font color=\"#FFFFFF\">ظن نقض بند ۸۶ قانون کیفری،</font>\n<font color=\"#FFFFFF\">توزیع ابزار تبلیغاتی</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#FFFFFF\">verfassungswidriger Organisationen.</font>",
    "text": "<font color=\"#FFFFFF\">سازمان‌های ضد قانون اساسی</font>"
  },
  {
    "id": 8,
    "source": "<font color=\"#FFFFFF\">Na ja, Eckner, so weit würde ich...</font>\n<font color=\"#FFFFFF\">- Was hier passiert, ist so crazy.</font>",
    "text": "<font color=\"#FFFFFF\">خب، اک‌نر، دیگه نه تا این حد...</font>\n<font color=\"#FFFFFF\">- چیزی که اینجا داره می‌گذره خیلی عجیبه</font>"
  },
  {
    "id": 9,
    "source": "<font color=\"#FFFFFF\">Und alle machen die Augen zu.</font>",
    "text": "<font color=\"#FFFFFF\">و همه هم چشماشون رو بستن</font>"
  },
  {
    "id": 10,
    "source": "<font color=\"#FFFFFF\">Wenn keiner hinguckt</font>\n<font color=\"#FFFFFF\">und ein Verbrechen passiert,</font>",
    "text": "<font color=\"#FFFFFF\">وقتی کسی حواسش نیست</font>\n<font color=\"#FFFFFF\">و یه جرم داره اتفاق می‌افته،</font>"
  },
  {
    "id": 11,
    "source": "<font color=\"#FFFFFF\">muss man</font>\n<font color=\"#FFFFFF\">mit zivilem Ungehorsam antworten.</font>",
    "text": "<font color=\"#FFFFFF\">باید با</font>\n<font color=\"#FFFFFF\">نافرمانی مدنی جوابشون رو داد</font>"
  },
  {
    "id": 12,
    "source": "<font color=\"#00FF00\">Was für ein Verbrechen?</font>\n<font color=\"#FFFFFF\">Die wollen den Golfplatz ausbauen.</font>",
    "text": "<font color=\"#00FF00\">کدوم جرم؟</font>\n<font color=\"#FFFFFF\">می‌خوان زمین گلف رو گسترش بدن</font>"
  },
  {
    "id": 13,
    "source": "<font color=\"#FFFFFF\">Der zieht so viel Wasser...</font>",
    "text": "<font color=\"#FFFFFF\">کلی آب مصرف می‌کنه...</font>"
  },
  {
    "id": 14,
    "source": "<font color=\"#00FFFF\">Weißt du,</font>\n<font color=\"#00FFFF\">was ziviler Ungehorsam bedeutet?</font>",
    "text": "<font color=\"#00FFFF\">می‌دونی</font>\n<font color=\"#00FFFF\">نافرمانی مدنی یعنی چی؟</font>"
  },
  {
    "id": 15,
    "source": "<font color=\"#00FF00\">Hat sie gerade gesagt, wenn man mit</font>\n<font color=\"#00FF00\">Mitteln des friedlichen Protests</font>",
    "text": "<font color=\"#00FF00\">الان گفت که اگه با</font>\n<font color=\"#00FF00\">روش‌های اعتراض مسالمت‌آمیز</font>"
  },
  {
    "id": 16,
    "source": "<font color=\"#00FF00\">gegen autoritäre Strukturen angeht,</font>",
    "text": "<font color=\"#00FF00\">به ساختارهای اقتدارگرا حمله کنی،</font>"
  },
  {
    "id": 17,
    "source": "<font color=\"#00FF00\">obwohl sie</font>\n<font color=\"#00FF00\">vom Gesetz her verboten sind.</font>",
    "text": "<font color=\"#00FF00\">حتی اگه</font>\n<font color=\"#00FF00\">از نظر قانونی ممنوع باشن</font>"
  },
  {
    "id": 18,
    "source": "<font color=\"#00FF00\">Ziviler Ungehorsam ist Pflicht,</font>\n<font color=\"#00FF00\">das sagte Henry David Thoreau.</font>",
    "text": "<font color=\"#00FF00\">نافرمانی مدنی یه وظیفه‌ست،</font>\n<font color=\"#00FF00\">این رو هنری دیوید ثورو گفته</font>"
  },
  {
    "id": 19,
    "source": "<font color=\"#FFFFFF\">Thoreau war ein alter, weißer Mann.</font>",
    "text": "<font color=\"#FFFFFF\">ثورو یه پیرمرد سفیدپوست بود</font>"
  },
  {
    "id": 20,
    "source": "<font color=\"#00FF00\">Dann Gandhi,</font>\n<font color=\"#00FF00\">der hat was Ähnliches gesagt.</font>",
    "text": "<font color=\"#00FF00\">پس گاندی،</font>\n<font color=\"#00FF00\">اونم یه چیز مشابه گفته بود</font>"
  },
  {
    "id": 21,
    "source": "<font color=\"#FFFFFF\">Gandhi war noch älter</font>\n<font color=\"#FFFFFF\">und ein misogynes Schwein.</font>",
    "text": "<font color=\"#FFFFFF\">گاندی از اونم پیرتر بود</font>\n<font color=\"#FFFFFF\">و یه عوضی زن‌ستیز بود</font>"
  },
  {
    "id": 22,
    "source": "<font color=\"#00FF00\">Ich argumentiere für dich,</font>\n<font color=\"#00FF00\">nicht gegen dich.</font>",
    "text": "<font color=\"#00FF00\">من دارم به نفع تو حرف می‌زنم،</font>\n<font color=\"#00FF00\">نه علیه تو</font>"
  },
  {
    "id": 23,
    "source": "<font color=\"#FFFFFF\">Sie sollten</font>\n<font color=\"#FFFFFF\">den Kindern mal beibringen,</font>",
    "text": "<font color=\"#FFFFFF\">شما باید</font>\n<font color=\"#FFFFFF\">به این بچه‌ها یاد بدید که</font>"
  },
  {
    "id": 24,
    "source": "<font color=\"#FFFFFF\">dass man nicht</font>\n<font color=\"#FFFFFF\">an Plakatwände schmiert.</font>",
    "text": "<font color=\"#FFFFFF\">نباید روی</font>\n<font color=\"#FFFFFF\">تابلوهای تبلیغاتی چیزی بنویسن</font>"
  },
  {
    "id": 25,
    "source": "<font color=\"#00FFFF\">Da haben Sie recht.</font>\n<font color=\"#00FFFF\">Das habe ich versucht...</font>",
    "text": "<font color=\"#00FFFF\">حق با شماست</font>\n<font color=\"#00FFFF\">من سعی کردم...</font>"
  }
]

[
  {
    "id": 1,
    "source": "<font color=\"#00FF00\">Ich bin stolz, dass Zoe</font>\n<font color=\"#00FF00\">sich gegen eine Maßnahme wehrt,</font>",
    "text": "<font color=\"#00FF00\">خیلی به زوئی افتخار می‌کنم که</font>\n<font color=\"#00FF00\">داره جلوی یه طرحی می‌ایسته</font>"
  },
  {
    "id": 2,
    "source": "<font color=\"#00FF00\">die so problematisch ist,</font>\n<font color=\"#00FF00\">wie der Golfsport dumm ist.</font>",
    "text": "<font color=\"#00FF00\">که به اندازه حماقتِ ورزش گلف</font>\n<font color=\"#00FF00\">مشکل‌ساز و احمقانه‌ست</font>"
  },
  {
    "id": 3,
    "source": "<font color=\"#00FF00\">Wenn man das \"Sport\" nennen kann.</font>\n<font color=\"#FFFFFF\">So.</font>",
    "text": "<font color=\"#00FF00\">البته اگه بشه اسمشو گذاشت ورزش</font>\n<font color=\"#FFFFFF\">خب</font>"
  },
  {
    "id": 4,
    "source": "<font color=\"#FFFFFF\">Morgen</font>\n<font color=\"#FFFFFF\">ist die Schmiererei überklebt.</font>",
    "text": "<font color=\"#FFFFFF\">فردا</font>\n<font color=\"#FFFFFF\">اون گندکاری‌ها رو می‌پوشونیم</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#FFFFFF\">Kontakt zur Druckerei haben wir.</font>",
    "text": "<font color=\"#FFFFFF\">با چاپخونه هماهنگ کردیم</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#FFFFFF\">Pinsel und Kleister</font>\n<font color=\"#FFFFFF\">besorgen Sie selbständig.</font>",
    "text": "<font color=\"#FFFFFF\">قلم‌مو و چسب رو هم</font>\n<font color=\"#FFFFFF\">خودتون باید تهیه کنید</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#FFFFFF\">Und wenn das alles gemacht ist,</font>\n<font color=\"#FFFFFF\">und nur dann,</font>",
    "text": "<font color=\"#FFFFFF\">و وقتی همه‌ش انجام شد</font>\n<font color=\"#FFFFFF\">فقط در اون صورته که</font>"
  },
  {
    "id": 8,
    "source": "<font color=\"#FFFFFF\">drücken wir noch mal ein Auge zu.</font>",
    "text": "<font color=\"#FFFFFF\">شاید یه چشم‌پوشی بکنیم</font>"
  },
  {
    "id": 9,
    "source": "<font color=\"#FFFF00\">Vergiss nicht,</font>\n<font color=\"#FFFF00\">von jetzt an nennst du mich Pierre.</font>",
    "text": "<font color=\"#FFFF00\">یادت نره</font>\n<font color=\"#FFFF00\">از الان به بعد بهم می‌گی پیر</font>"
  },
  {
    "id": 10,
    "source": "<font color=\"#FFFFFF\">Kann ich nicht Papa sagen?</font>\n<font color=\"#FFFF00\">Das geht auch.</font>",
    "text": "<font color=\"#FFFFFF\">نمی‌تونم بگم بابا؟</font>\n<font color=\"#FFFF00\">اونم میشه</font>"
  },
  {
    "id": 11,
    "source": "<font color=\"#FFFFFF\">Entschuldigung.</font>\n<font color=\"#FFFF00\">Nicht stehen bleiben.</font>",
    "text": "<font color=\"#FFFFFF\">ببخشید</font>\n<font color=\"#FFFF00\">واینستا، راه بیفت</font>"
  },
  {
    "id": 12,
    "source": "<font color=\"#FFFFFF\">Entschuldigung?</font>\n<font color=\"#FFFFFF\">- Der meint uns.</font>",
    "text": "<font color=\"#FFFFFF\">ببخشید؟</font>\n<font color=\"#FFFFFF\">- با ماست</font>"
  },
  {
    "id": 13,
    "source": "<font color=\"#FFFF00\">Der meint uns nicht, mach schon.</font>\n<font color=\"#FFFFFF\">Ihr zwei.</font>",
    "text": "<font color=\"#FFFF00\">با ما نیست، زود باش</font>\n<font color=\"#FFFFFF\">شما دو تا</font>"
  },
  {
    "id": 14,
    "source": "<font color=\"#FFFFFF\">Hallo? Ich rede mit euch.</font>\n<font color=\"#FFFF00\">(mit Akzent) Bitte?</font>",
    "text": "<font color=\"#FFFFFF\">الو؟ با شما دوتام</font>\n<font color=\"#FFFF00\">بله؟</font>"
  },
  {
    "id": 15,
    "source": "<font color=\"#FFFF00\">Mon Dieu.</font>",
    "text": "<font color=\"#FFFF00\">خدای من</font>"
  },
  {
    "id": 16,
    "source": "<font color=\"#FFFFFF\">Andi, was soll das? Dich erkennt</font>\n<font color=\"#FFFFFF\">ein Blinder mit Krückstock.</font>",
    "text": "<font color=\"#FFFFFF\">اندی، این چه مسخره‌بازی‌ایه؟ یه آدم کور هم</font>\n<font color=\"#FFFFFF\">با عصا تو رو از صد فرسخی می‌شناسه</font>"
  },
  {
    "id": 17,
    "source": "<font color=\"#FFFFFF\">Du kannst nicht aufs Gelände,</font>\n<font color=\"#FFFFFF\">du hast Platzverbot.</font>",
    "text": "<font color=\"#FFFFFF\">نمی‌تونی بیای تو محوطه</font>\n<font color=\"#FFFFFF\">ورودت ممنوعه</font>"
  },
  {
    "id": 18,
    "source": "<font color=\"#FFFF00\">Ich will nur</font>\n<font color=\"#FFFF00\">meinen Lümmel zum Turnier anmelden.</font>",
    "text": "<font color=\"#FFFF00\">فقط می‌خوام</font>\n<font color=\"#FFFF00\">پسرمو واسه مسابقه ثبت‌نام کنم</font>"
  },
  {
    "id": 19,
    "source": "<font color=\"#FFFF00\">Geht nur im Beisein</font>\n<font color=\"#FFFF00\">eines Erziehungsberechtigten.</font>",
    "text": "<font color=\"#FFFF00\">فقط با حضور</font>\n<font color=\"#FFFF00\">سرپرست قانونی میشه</font>"
  },
  {
    "id": 20,
    "source": "<font color=\"#FFFFFF\">Wenn Gert dich sieht,</font>\n<font color=\"#FFFFFF\">dann bin ich meinen Job los.</font>",
    "text": "<font color=\"#FFFFFF\">اگه گرت تو رو ببینه</font>\n<font color=\"#FFFFFF\">کارم تمومه</font>"
  },
  {
    "id": 21,
    "source": "<font color=\"#FFFF00\">Ist ein Ehrenamt.</font>\n<font color=\"#FFFFFF\">Ja, aber ein entspanntes.</font>",
    "text": "<font color=\"#FFFF00\">یه کار افتخاریه دیگه</font>\n<font color=\"#FFFFFF\">آره، ولی کارِ راحتیه</font>"
  },
  {
    "id": 22,
    "source": "<font color=\"#FFFFFF\">Du kannst nirgends</font>\n<font color=\"#FFFFFF\">so gut essen wie hier,</font>",
    "text": "<font color=\"#FFFFFF\">هیچ‌جا نمی‌تونی</font>\n<font color=\"#FFFFFF\">به این خوبی غذا بخوری</font>"
  },
  {
    "id": 23,
    "source": "<font color=\"#FFFFFF\">manchmal kriege ich Nudeln umsonst.</font>",
    "text": "<font color=\"#FFFFFF\">گاهی وقتا هم مجانی بهم پاستا میدن</font>"
  },
  {
    "id": 24,
    "source": "<font color=\"#FFFF00\">Pass mal auf, Sascha.</font>\n<font color=\"#FFFF00\">Das ist wichtig.</font>",
    "text": "<font color=\"#FFFF00\">ببین ساشا</font>\n<font color=\"#FFFF00\">این خیلی مهمه</font>"
  },
  {
    "id": 25,
    "source": "<font color=\"#FFFF00\">Wenn Rocco das größte Golftalent</font>\n<font color=\"#FFFF00\">seiner Generation ist,</font>",
    "text": "<font color=\"#FFFF00\">اگه روکو بزرگترین استعداد گلف</font>\n<font color=\"#FFFF00\">نسل خودشه</font>"
  }
]

[
  {
    "id": 1,
    "source": "<font color=\"#FFFF00\">es aber daran scheitert, dass du</font>\n<font color=\"#FFFF00\">päpstlicher bist als der Papst?</font>",
    "text": "<font color=\"#FFFF00\">ولی مشکل اینجاست که تو</font>\n<font color=\"#FFFF00\">از پاپ هم کاتولیک‌تری؟</font>"
  },
  {
    "id": 2,
    "source": "<font color=\"#FFFF00\">Kannst du das</font>\n<font color=\"#FFFF00\">mit deiner Golfer-Ehre vereinbaren?</font>",
    "text": "<font color=\"#FFFF00\">می‌تونی اینو با</font>\n<font color=\"#FFFF00\">شرف گلف‌بازی‌ت کنار بیای؟</font>"
  },
  {
    "id": 3,
    "source": "<font color=\"#FFFFFF\">Na gut, aber reiß dich zusammen.</font>",
    "text": "<font color=\"#FFFFFF\">خیلی خب، ولی خودتو جمع‌وجور کن</font>"
  },
  {
    "id": 4,
    "source": "<font color=\"#FFFF00\">Komm.</font>",
    "text": "<font color=\"#FFFF00\">بزن بریم</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#FFFF00\">Rocco?</font>",
    "text": "<font color=\"#FFFF00\">روکو؟</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#FFFFFF\">Schönes Spiel.</font>\n<font color=\"#FFFF00\">Komm, Rocci.</font>",
    "text": "<font color=\"#FFFFFF\">بازی خوبی داشته باشی</font>\n<font color=\"#FFFF00\">بیا روکی</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#FFFFFF\">Warum hast du Platzverbot, Papa?</font>",
    "text": "<font color=\"#FFFFFF\">بابا، چرا از زمین گلف اخراج شدی؟</font>"
  },
  {
    "id": 8,
    "source": "<font color=\"#FFFF00\">Ich habe mal,</font>\n<font color=\"#FFFF00\">als ich noch Mitglied war,</font>",
    "text": "<font color=\"#FFFF00\">یه بار،</font>\n<font color=\"#FFFF00\">وقتی هنوز عضو بودم،</font>"
  },
  {
    "id": 9,
    "source": "<font color=\"#FFFF00\">den Besitzer aus Versehen</font>\n<font color=\"#FFFF00\">mit dem Querschläger abgeschossen.</font>",
    "text": "<font color=\"#FFFF00\">اشتباهی با توپ گلف</font>\n<font color=\"#FFFF00\">زدم تو کله صاحب باشگاه</font>"
  },
  {
    "id": 10,
    "source": "<font color=\"#FFFFFF\">Ist er tot?</font>",
    "text": "<font color=\"#FFFFFF\">مرد؟</font>"
  },
  {
    "id": 11,
    "source": "<font color=\"#FFFF00\">Schön wäre es.</font>\n<font color=\"#FFFF00\">Nee, der sitzt im Rollstuhl.</font>",
    "text": "<font color=\"#FFFF00\">کاش می‌مرد</font>\n<font color=\"#FFFF00\">نه، الان ویلچرنشین شده</font>"
  },
  {
    "id": 12,
    "source": "<font color=\"#FFFF00\">Es war gar nicht so schlimm,</font>\n<font color=\"#FFFF00\">Streifschuss, sage ich mal.</font>",
    "text": "<font color=\"#FFFF00\">اونقدرها هم بد نبود،</font>\n<font color=\"#FFFF00\">فقط یه خراش سطحی بود</font>"
  },
  {
    "id": 13,
    "source": "<font color=\"#FFFF00\">Aber der hatte was mit der Hüfte,</font>\n<font color=\"#FFFF00\">kein Wunder bei seinem Gewicht.</font>",
    "text": "<font color=\"#FFFF00\">ولی لگنش مشکل داشت،</font>\n<font color=\"#FFFF00\">با اون وزنی که داشت، تعجبی هم نداره</font>"
  },
  {
    "id": 14,
    "source": "<font color=\"#FFFF00\">Da brauchten sie</font>\n<font color=\"#FFFF00\">einen schwarzen Peter.</font>",
    "text": "<font color=\"#FFFF00\">اونا هم دنبال</font>\n<font color=\"#FFFF00\">یه مقصر می‌گشتن</font>"
  },
  {
    "id": 15,
    "source": "<font color=\"#FFFFFF\">Aber ich bin nicht Peter, sondern?</font>",
    "text": "<font color=\"#FFFFFF\">ولی من پیتر نیستم، پس چی‌ام؟</font>"
  },
  {
    "id": 16,
    "source": "<font color=\"#FFFFFF\">Pierre.</font>\n<font color=\"#FFFF00\">Richtig.</font>",
    "text": "<font color=\"#FFFFFF\">پی‌یر</font>\n<font color=\"#FFFF00\">آفرین</font>"
  },
  {
    "id": 17,
    "source": "<font color=\"#FFFFFF\">Sie wollen sich</font>\n<font color=\"#FFFFFF\">fürs Turnier anmelden?</font>",
    "text": "<font color=\"#FFFFFF\">می‌خواید برای</font>\n<font color=\"#FFFFFF\">مسابقات ثبت‌نام کنید؟</font>"
  },
  {
    "id": 18,
    "source": "<font color=\"#FFFF00\">(mit Akzent)</font>\n<font color=\"#FFFF00\">Ähm, die lebenslange Mitgliedschaft</font>",
    "text": "<font color=\"#FFFF00\">(با لهجه)</font>\n<font color=\"#FFFF00\">امم، عضویت مادام‌العمر</font>"
  },
  {
    "id": 19,
    "source": "<font color=\"#FFFF00\">äh,</font>\n<font color=\"#FFFF00\">gilt auch für den neuen Golfclub?</font>",
    "text": "<font color=\"#FFFF00\">اِ،</font>\n<font color=\"#FFFF00\">شامل این باشگاه گلف جدید هم می‌شه؟</font>"
  },
  {
    "id": 20,
    "source": "<font color=\"#FFFFFF\">Ja, aber nur,</font>\n<font color=\"#FFFFFF\">wenn Sie das Turnier auch gewinnen.</font>",
    "text": "<font color=\"#FFFFFF\">بله، ولی فقط</font>\n<font color=\"#FFFFFF\">اگه توی مسابقات برنده بشید</font>"
  },
  {
    "id": 21,
    "source": "<font color=\"#FFFFFF\">Gut. Wie ist denn Ihr Name?</font>\n<font color=\"#FFFF00\">Ich will gar nicht mitspielen.</font>",
    "text": "<font color=\"#FFFFFF\">خیلی خب، اسمتون چیه؟</font>\n<font color=\"#FFFF00\">من که نمی‌خوام بازی کنم</font>"
  },
  {
    "id": 22,
    "source": "<font color=\"#FFFF00\">Aber mein Sohn hier.</font>",
    "text": "<font color=\"#FFFF00\">ولی پسرم اینجا می‌خواد بازی کنه</font>"
  },
  {
    "id": 23,
    "source": "<font color=\"#FFFF00\">Den können Sie einschreiben.</font>",
    "text": "<font color=\"#FFFF00\">می‌تونید اسم اونو بنویسید</font>"
  },
  {
    "id": 24,
    "source": "<font color=\"#FFFFFF\">Fantastisch. Sie haben sicherlich</font>\n<font color=\"#FFFFFF\">einen Personalausweis für mich?</font>",
    "text": "<font color=\"#FFFFFF\">عالیه. حتماً کارت شناسایی</font>\n<font color=\"#FFFFFF\">ایشون رو همراهتون دارید؟</font>"
  },
  {
    "id": 25,
    "source": "<font color=\"#FFFF00\">Glauben Sie nicht,</font>\n<font color=\"#FFFF00\">dass er mein Sohn ist? Oder was?</font>",
    "text": "<font color=\"#FFFF00\">باورتون نمی‌شه</font>\n<font color=\"#FFFF00\">که پسرمه؟ یا چی؟</font>"
  }
]

[
  {
    "id": 1,
    "source": "<font color=\"#FFFFFF\">Na ja... Also, äh, besonders</font>\n<font color=\"#FFFFFF\">ähnlich sehen Sie sich nicht.</font>",
    "text": "<font color=\"#FFFFFF\">خب... راستش، خب، خیلی هم</font>\n<font color=\"#FFFFFF\">شبیه هم نیستید</font>"
  },
  {
    "id": 2,
    "source": "<font color=\"#FFFF00\">Rocco hat</font>\n<font color=\"#FFFF00\">seinen Kinderausweis nicht dabei.</font>",
    "text": "<font color=\"#FFFF00\">روکو کارت شناسایی‌اش</font>\n<font color=\"#FFFF00\">همراش نیست</font>"
  },
  {
    "id": 3,
    "source": "<font color=\"#FFFFFF\">Dann geht das leider nicht.</font>\n<font color=\"#FFFF00\">Äh... Pourquoi?</font>",
    "text": "<font color=\"#FFFFFF\">پس متأسفانه نمی‌شه</font>\n<font color=\"#FFFF00\">اِ... چرا؟</font>"
  },
  {
    "id": 4,
    "source": "<font color=\"#FFFFFF\">Alles in Ordnung, Maus?</font>\n<font color=\"#FFFFFF\">- Ja.</font>",
    "text": "<font color=\"#FFFFFF\">همه‌چی روبه‌راهه موش‌موشک؟</font>\n<font color=\"#FFFFFF\">- آره</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#FFFFFF\">Ich muss die Spielregeln erklären.</font>",
    "text": "<font color=\"#FFFFFF\">باید قوانین بازی رو توضیح بدم</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#FFFFFF\">Pierre hat meinen Ausweis vergessen</font>\n<font color=\"#FFFFFF\">und wir dürfen nicht mitmachen.</font>",
    "text": "<font color=\"#FFFFFF\">پی‌یر کارت شناسایی‌ام رو جا گذاشته</font>\n<font color=\"#FFFFFF\">و اجازه نداریم شرکت کنیم</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#FFFFFF\">So ist das nun mal.</font>\n<font color=\"#FFFFFF\">- Schatz, lass doch.</font>",
    "text": "<font color=\"#FFFFFF\">خب دیگه، همینه که هست</font>\n<font color=\"#FFFFFF\">- عزیزم، ولش کن</font>"
  },
  {
    "id": 8,
    "source": "<font color=\"#FFFFFF\">Dann drücken wir eben ein Auge zu.</font>\n<font color=\"#FFFF00\">Sie sind ja ein echter Machertyp.</font>",
    "text": "<font color=\"#FFFFFF\">پس یه چشم‌پوشی می‌کنیم</font>\n<font color=\"#FFFF00\">شما واقعاً آدمِ کاردرستی هستید</font>"
  },
  {
    "id": 9,
    "source": "<font color=\"#FFFF00\">Was, Jochen?</font>\n<font color=\"#FFFFFF\">Entschuldigung. Kennen wir uns?</font>",
    "text": "<font color=\"#FFFF00\">چی، یوخن؟</font>\n<font color=\"#FFFFFF\">ببخشید، ما همدیگه رو می‌شناسیم؟</font>"
  },
  {
    "id": 10,
    "source": "<font color=\"#FFFF00\">Ich kenne Sie.</font>",
    "text": "<font color=\"#FFFF00\">من شما رو می‌شناسم</font>"
  },
  {
    "id": 11,
    "source": "<font color=\"#FFFFFF\">Von der Werbung. Deshalb sind</font>\n<font color=\"#FFFFFF\">wir auch hier. Wegen dem Turnier.</font>",
    "text": "<font color=\"#FFFFFF\">از توی تبلیغات. واسه همینم</font>\n<font color=\"#FFFFFF\">اینجاییم. به‌خاطر مسابقات</font>"
  },
  {
    "id": 12,
    "source": "<font color=\"#FFFFFF\">Ach so, klar.</font>",
    "text": "<font color=\"#FFFFFF\">آهان، خب معلومه</font>"
  },
  {
    "id": 13,
    "source": "<font color=\"#FFFFFF\">Natürlich.</font>",
    "text": "<font color=\"#FFFFFF\">البته</font>"
  },
  {
    "id": 14,
    "source": "<font color=\"#FFFFFF\">Ähm ... ist okay.</font>",
    "text": "<font color=\"#FFFFFF\">اِ... باشه، حله</font>"
  },
  {
    "id": 15,
    "source": "<font color=\"#FFFFFF\">Gut.</font>\n<font color=\"#FFFFFF\">- Viel Glück, junger Mann.</font>",
    "text": "<font color=\"#FFFFFF\">خوبه</font>\n<font color=\"#FFFFFF\">- موفق باشی پسر جون</font>"
  },
  {
    "id": 16,
    "source": "<font color=\"#FFFFFF\">Tschüss.</font>",
    "text": "<font color=\"#FFFFFF\">خداحافظ</font>"
  },
  {
    "id": 17,
    "source": "<font color=\"#FFFF00\">Au revoir.</font>",
    "text": "<font color=\"#FFFF00\">اُرووار</font>"
  },
  {
    "id": 18,
    "source": "<font color=\"#FFFFFF\">Also, wie ist denn dein Name?</font>\n<font color=\"#FFFF00\">Knüppé.</font>",
    "text": "<font color=\"#FFFFFF\">خب، اسمت چیه؟</font>\n<font color=\"#FFFF00\">کونوپه</font>"
  },
  {
    "id": 19,
    "source": "<font color=\"#FFFF00\">So wie \"Knuppe\"</font>\n<font color=\"#FFFF00\">nur mit einem Akzent.</font>",
    "text": "<font color=\"#FFFF00\">مثل «کنوپه»</font>\n<font color=\"#FFFF00\">فقط با یه لهجه خاص</font>"
  },
  {
    "id": 20,
    "source": "<font color=\"#FFFFFF\">* Sie lachen. *</font>",
    "text": "<font color=\"#FFFFFF\">* می‌خندند *</font>"
  },
  {
    "id": 21,
    "source": "<font color=\"#FFFFFF\">Mein Gott, so ein Scheiß, ey.</font>",
    "text": "<font color=\"#FFFFFF\">ای بابا، چه گندی، اه</font>"
  },
  {
    "id": 22,
    "source": "<font color=\"#FF00FF\">Was steht da?</font>\n<font color=\"#FF00FF\">Was kann man gewinnen?</font>",
    "text": "<font color=\"#FF00FF\">اونجا چی نوشته؟</font>\n<font color=\"#FF00FF\">چی می‌شه برد؟</font>"
  },
  {
    "id": 23,
    "source": "<font color=\"#FFFFFF\">Woher sollen wir denn das wissen?</font>\n<font color=\"#FF00FF\">Stell dich nicht so an, lies vor.</font>",
    "text": "<font color=\"#FFFFFF\">ما از کجا بدونیم؟</font>\n<font color=\"#FF00FF\">لوس نشو، بخونش دیگه</font>"
  },
  {
    "id": 24,
    "source": "<font color=\"#FF00FF\">Ich habe meine Brille vergessen.</font>\n<font color=\"#FFFFFF\">Da steht gar nichts.</font>",
    "text": "<font color=\"#FF00FF\">عینکم رو یادم رفته</font>\n<font color=\"#FFFFFF\">اصلاً چیزی اونجا ننوشته</font>"
  },
  {
    "id": 25,
    "source": "<font color=\"#FF00FF\">Ich sehe, dass da was steht.</font>\n<font color=\"#FFFFFF\">Aber nichts zum Preisgeld.</font>",
    "text": "<font color=\"#FF00FF\">می‌بینم که یه چیزی نوشته</font>\n<font color=\"#FFFFFF\">ولی هیچی درباره جایزه نقدی نیست</font>"
  }
]

[
  {
    "id": 1,
    "source": "<font color=\"#FF00FF\">Werde nicht frech, Fräulein, ja?</font>\n<font color=\"#FF00FF\">Das Kleingedruckte.</font>",
    "text": "<font color=\"#FF00FF\">زبون‌دراز نشو، خانم کوچولو، شنیدی؟</font>\n<font color=\"#FF00FF\">اون ریزنوشته‌ها رو ببین</font>"
  },
  {
    "id": 2,
    "source": "<font color=\"#FFFFFF\">Hier steht \"Teilnahme kostenlos\"</font>\n<font color=\"#FFFFFF\">und ein QR-Code.</font>",
    "text": "<font color=\"#FFFFFF\">اینجا نوشته «شرکت رایگان»</font>\n<font color=\"#FFFFFF\">و یه کد کیوآر هم داره</font>"
  },
  {
    "id": 3,
    "source": "<font color=\"#FF00FF\">Mach mal mit dem Handy.</font>",
    "text": "<font color=\"#FF00FF\">با گوشیت امتحان کن</font>"
  },
  {
    "id": 4,
    "source": "<font color=\"#FF00FF\">Bist du nicht die von der Dorit?</font>",
    "text": "<font color=\"#FF00FF\">تو همون دخترِ دوریتی نیستی؟</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#FF00FF\">Die ist eine meiner längsten</font>\n<font color=\"#FF00FF\">Kunden, ich weiß alles über dich.</font>",
    "text": "<font color=\"#FF00FF\">اون از قدیمی‌ترین مشتری‌های منه،</font>\n<font color=\"#FF00FF\">من همه چی رو درباره‌ت می‌دونم</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#FFFFFF\">\"Lebenslange Mitgliedschaft.</font>",
    "text": "<font color=\"#FFFFFF\">«عضویت مادام‌العمر</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#FFFFFF\">10.000 Euro.\"</font>",
    "text": "<font color=\"#FFFFFF\">۱۰ هزار یورو»</font>"
  },
  {
    "id": 8,
    "source": "<font color=\"#FFFFFF\">Und so Golfsachen...</font>",
    "text": "<font color=\"#FFFFFF\">و یه سری وسایل گلف...</font>"
  },
  {
    "id": 9,
    "source": "<font color=\"#FF00FF\">Hm. Danke, Püppi.</font>",
    "text": "<font color=\"#FF00FF\">هوم، مرسی عروسک</font>"
  },
  {
    "id": 10,
    "source": "<font color=\"#FFFFFF\">So weird, Alter.</font>",
    "text": "<font color=\"#FFFFFF\">خیلی عجیبه، پسر</font>"
  },
  {
    "id": 11,
    "source": "<font color=\"#FFFF00\">So.</font>",
    "text": "<font color=\"#FFFF00\">خب</font>"
  },
  {
    "id": 12,
    "source": "<font color=\"#FFFFFF\">Einfach ganz weit weg schlagen?</font>\n<font color=\"#FFFF00\">Ganz Genau.</font>",
    "text": "<font color=\"#FFFFFF\">فقط باید خیلی دور بزنیش؟</font>\n<font color=\"#FFFF00\">دقیقاً</font>"
  },
  {
    "id": 13,
    "source": "<font color=\"#FFFF00\">Alter Schwede!</font>",
    "text": "<font color=\"#FFFF00\">ایول بابا</font>"
  },
  {
    "id": 14,
    "source": "<font color=\"#FFFF00\">Sag mal, Rocci, was bist du</font>\n<font color=\"#FFFF00\">denn für ein geiler Typ, ey.</font>",
    "text": "<font color=\"#FFFF00\">بگو ببینم روکی، تو دیگه چه نابغه‌ای هستی</font>\n<font color=\"#FFFF00\">دمت گرم</font>"
  },
  {
    "id": 15,
    "source": "<font color=\"#FFFF00\">Das ist ja der Wahnsinn.</font>",
    "text": "<font color=\"#FFFF00\">این فوق‌العاده‌ست</font>"
  },
  {
    "id": 16,
    "source": "<font color=\"#FFFF00\">So gewinnen wir auf alle Fälle, du.</font>\n<font color=\"#FFFF00\">Komm her, mein Kleiner.</font>",
    "text": "<font color=\"#FFFF00\">با این وضع حتماً می‌بریم</font>\n<font color=\"#FFFF00\">بیا اینجا ببینم پسر</font>"
  },
  {
    "id": 17,
    "source": "<font color=\"#FFFF00\">Weißt du, wie lieb ich dich habe?</font>\n<font color=\"#FFFF00\">Komm, gleich noch mal.</font>",
    "text": "<font color=\"#FFFF00\">می‌دونی چقدر دوست دارم؟</font>\n<font color=\"#FFFF00\">بیا، دوباره بزن</font>"
  },
  {
    "id": 18,
    "source": "<font color=\"#FFFF00\">Ja, haha.</font>\n<font color=\"#FFFF00\">Sehr witzig, du Knalltüte.</font>",
    "text": "<font color=\"#FFFF00\">آره، هاها</font>\n<font color=\"#FFFF00\">خیلی بامزه‌ای، خل و چل</font>"
  },
  {
    "id": 19,
    "source": "<font color=\"#FFFF00\">So, komm, gleich noch mal.</font>",
    "text": "<font color=\"#FFFF00\">خب، بیا، دوباره بزن</font>"
  },
  {
    "id": 20,
    "source": "<font color=\"#FFFF00\">Bist du bescheuert?</font>",
    "text": "<font color=\"#FFFF00\">مخ‌ت تاب برداشته؟</font>"
  },
  {
    "id": 21,
    "source": "<font color=\"#FFFF00\">Das ist...</font>",
    "text": "<font color=\"#FFFF00\">این...</font>"
  },
  {
    "id": 22,
    "source": "<font color=\"#FFFF00\">Was ist denn los?</font>\n<font color=\"#FFFFFF\">Keine Ahnung.</font>",
    "text": "<font color=\"#FFFF00\">چی شده؟</font>\n<font color=\"#FFFFFF\">نمی‌دونم</font>"
  },
  {
    "id": 23,
    "source": "<font color=\"#FFFF00\">Willst du nicht, oder?</font>",
    "text": "<font color=\"#FFFF00\">نمی‌خوای یا چی؟</font>"
  },
  {
    "id": 24,
    "source": "<font color=\"#FFFF00\">Du musst ehrgeiziger sein, Rocco.</font>",
    "text": "<font color=\"#FFFF00\">باید بیشتر تلاش کنی، روکو</font>"
  },
  {
    "id": 25,
    "source": "<font color=\"#FFFF00\">Du musst das wollen,</font>\n<font color=\"#FFFF00\">und zwar so richtig.</font>",
    "text": "<font color=\"#FFFF00\">باید واقعاً بخوای،</font>\n<font color=\"#FFFF00\">با تمام وجودت</font>"
  }
]

[
  {
    "id": 1,
    "source": "<font color=\"#FFFFFF\">* Scheppern *</font>",
    "text": "<font color=\"#FFFFFF\">* صدای خرت‌وپرت *</font>"
  },
  {
    "id": 2,
    "source": "<font color=\"#FFFFFF\">(Mann) Oh Mann!</font>",
    "text": "<font color=\"#FFFFFF\">(مرد) ای بابا!</font>"
  },
  {
    "id": 3,
    "source": "<font color=\"#FFFF00\">Die größten Männer der Geschichte</font>\n<font color=\"#FFFF00\">waren die mit dem größten Ehrgeiz.</font>",
    "text": "<font color=\"#FFFF00\">بزرگ‌ترین مردهای تاریخ،</font>\n<font color=\"#FFFF00\">اونایی بودن که بیشترین جاه‌طلبی رو داشتن</font>"
  },
  {
    "id": 4,
    "source": "<font color=\"#FFFF00\">Lothar Matthäus.</font>",
    "text": "<font color=\"#FFFF00\">لوتار ماتئوس</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#FFFF00\">Peter Maffay.</font>",
    "text": "<font color=\"#FFFF00\">پیتر مافای</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#FFFF00\">Angela Merkel.</font>",
    "text": "<font color=\"#FFFF00\">آنگلا مرکل</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#FFFF00\">Rocci? Wo ist denn der Lümmel?</font>",
    "text": "<font color=\"#FFFF00\">روکی؟ این وروجک کجاست؟</font>"
  },
  {
    "id": 8,
    "source": "<font color=\"#FFFF00\">Rocci?</font>",
    "text": "<font color=\"#FFFF00\">روکی؟</font>"
  },
  {
    "id": 9,
    "source": "<font color=\"#FFFF00\">Was ist denn da?</font>",
    "text": "<font color=\"#FFFF00\">اونجا چه خبره؟</font>"
  },
  {
    "id": 10,
    "source": "<font color=\"#FFFF00\">Äh...</font>",
    "text": "<font color=\"#FFFF00\">اِ...</font>"
  },
  {
    "id": 11,
    "source": "<font color=\"#FFFF00\">Das... Das ist doch...</font>",
    "text": "<font color=\"#FFFF00\">این... این که...</font>"
  },
  {
    "id": 12,
    "source": "<font color=\"#FFFFFF\">Theodor Henri Kröger.</font>",
    "text": "<font color=\"#FFFFFF\">تئودور آنری کروگر</font>"
  },
  {
    "id": 13,
    "source": "<font color=\"#FFFF00\">Theodor?</font>\n<font color=\"#FFFFFF\">Theodor Henri Kröger.</font>",
    "text": "<font color=\"#FFFF00\">تئودور؟</font>\n<font color=\"#FFFFFF\">تئودور آنری کروگر</font>"
  },
  {
    "id": 14,
    "source": "<font color=\"#FFFFFF\">Der \"Bobbele des Golfsports\".</font>",
    "text": "<font color=\"#FFFFFF\">«بچه زرنگ گلف»</font>"
  },
  {
    "id": 15,
    "source": "<font color=\"#FFFFFF\">Das größte U18-Golftalent</font>\n<font color=\"#FFFFFF\">seiner Generation.</font>",
    "text": "<font color=\"#FFFFFF\">بزرگ‌ترین استعداد گلف زیر ۱۸ سال</font>\n<font color=\"#FFFFFF\">نسل خودش</font>"
  },
  {
    "id": 16,
    "source": "<font color=\"#FFFFFF\">Wenn er nur die Emotionen</font>\n<font color=\"#FFFFFF\">unter Kontrolle gehabt hätte.</font>",
    "text": "<font color=\"#FFFFFF\">کاش فقط می‌تونست</font>\n<font color=\"#FFFFFF\">احساساتش رو کنترل کنه</font>"
  },
  {
    "id": 17,
    "source": "<font color=\"#FFFFFF\">Was hat er gemacht?</font>",
    "text": "<font color=\"#FFFFFF\">چیکار کرده بود؟</font>"
  },
  {
    "id": 18,
    "source": "<font color=\"#FFFFFF\">Als Theodor Henri Kröger</font>\n<font color=\"#FFFFFF\">bei den Junior Golf Masters in Issum</font>",
    "text": "<font color=\"#FFFFFF\">وقتی تئودور آنری کروگر</font>\n<font color=\"#FFFFFF\">توی مسابقات گلف جوانان در ایسوم</font>"
  },
  {
    "id": 19,
    "source": "<font color=\"#FFFFFF\">wegen eines falsch sitzenden Polos</font>",
    "text": "<font color=\"#FFFFFF\">به خاطر بد وایسادنِ تیشرت پولو</font>"
  },
  {
    "id": 20,
    "source": "<font color=\"#FFFFFF\">zum Strafschlag verurteilt wurde,</font>\n<font color=\"#FFFFFF\">ist er so ausgerastet,</font>",
    "text": "<font color=\"#FFFFFF\">جریمه شد،</font>\n<font color=\"#FFFFFF\">اون‌قدر قاطی کرد که</font>"
  },
  {
    "id": 21,
    "source": "<font color=\"#FFFFFF\">dass er mit seinem Schläger</font>\n<font color=\"#FFFFFF\">auf die Juroren los ist.</font>",
    "text": "<font color=\"#FFFFFF\">با چوب گلفش</font>\n<font color=\"#FFFFFF\">به داورها حمله کرد</font>"
  },
  {
    "id": 22,
    "source": "<font color=\"#FFFFFF\">Seitdem warnt man sich in der</font>\n<font color=\"#FFFFFF\">Golfwelt immer mit \"Henri Fore\",</font>",
    "text": "<font color=\"#FFFFFF\">از اون موقع توی دنیای گلف</font>\n<font color=\"#FFFFFF\">همه رو با «آنری فور» خبر می‌کنن</font>"
  },
  {
    "id": 23,
    "source": "<font color=\"#FFFFFF\">wenn ein Spieler durchdreht</font>\n<font color=\"#FFFFFF\">und andere attackiert.</font>",
    "text": "<font color=\"#FFFFFF\">وقتی یه بازیکن قاطی می‌کنه</font>\n<font color=\"#FFFFFF\">و به بقیه حمله می‌کنه</font>"
  },
  {
    "id": 24,
    "source": "<font color=\"#FFFFFF\">Wo ist Theodor Henri Kröger jetzt?</font>\n<font color=\"#FFFFFF\">- Verschwunden.</font>",
    "text": "<font color=\"#FFFFFF\">الان تئودور آنری کروگر کجاست؟</font>\n<font color=\"#FFFFFF\">- غیبش زده</font>"
  },
  {
    "id": 25,
    "source": "<font color=\"#FFFFFF\">* Rauschen *</font>\n<font color=\"#FFFFFF\">Moment.</font>",
    "text": "<font color=\"#FFFFFF\">* صدای نویز *</font>\n<font color=\"#FFFFFF\">یه لحظه</font>"
  }
]

[
  {
    "id": 1,
    "source": "<font color=\"#FFFFFF\">* Funkspruch *</font>",
    "text": "<font color=\"#FFFFFF\">* صدای بی‌سیم *</font>"
  },
  {
    "id": 2,
    "source": "<font color=\"#FFFFFF\">Jo, komme gleich.</font>\n<font color=\"#FFFFFF\">Muss noch kurz was aufsaugen.</font>",
    "text": "<font color=\"#FFFFFF\">آره، الان میام</font>\n<font color=\"#FFFFFF\">فقط باید یه چیزی رو جارو کنم</font>"
  },
  {
    "id": 3,
    "source": "<font color=\"#FFFFFF\">Theodor Henri Kröger</font>\n<font color=\"#FFFFFF\">hat die Golfwelt</font>",
    "text": "<font color=\"#FFFFFF\">تئودور هنری کروگر</font>\n<font color=\"#FFFFFF\">دنیای گلف رو</font>"
  },
  {
    "id": 4,
    "source": "<font color=\"#FFFFFF\">für einen kurzen Moment verzaubert</font>\n<font color=\"#FFFFFF\">und ihr dann den Rücken gekehrt.</font>",
    "text": "<font color=\"#FFFFFF\">برای لحظه‌ای کوتاه مسحور کرد</font>\n<font color=\"#FFFFFF\">و بعد پشتش رو بهش کرد</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#FFFFFF\">Niemand weiß,</font>\n<font color=\"#FFFFFF\">wohin ihn die Winde getragen haben.</font>",
    "text": "<font color=\"#FFFFFF\">هیچ‌کس نمی‌دونه</font>\n<font color=\"#FFFFFF\">که باد اون رو به کجا برده</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#FFFF00\">Quatsch.</font>\n<font color=\"#FFFF00\">Das ist Theo, mein Nachbar.</font>",
    "text": "<font color=\"#FFFF00\">چرت نگو</font>\n<font color=\"#FFFF00\">این تئوئه، همسایه‌مون</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#FFFF00\">Der wohnt gleich nebenan bei uns.</font>\n<font color=\"#FFFFFF\">Theodor Henri Kröger lebt?</font>",
    "text": "<font color=\"#FFFF00\">همین بغل دست ما زندگی می‌کنه</font>\n<font color=\"#FFFFFF\">تئودور هنری کروگر زنده‌ست؟</font>"
  },
  {
    "id": 8,
    "source": "<font color=\"#FFFF00\">Klar lebt der.</font>",
    "text": "<font color=\"#FFFF00\">معلومه که زنده‌ست</font>"
  },
  {
    "id": 9,
    "source": "<font color=\"#FFFFFF\">Der hat sogar eine Familie</font>\n<font color=\"#FFFFFF\">und ist Musiklehrer.</font>",
    "text": "<font color=\"#FFFFFF\">حتی خانواده هم داره</font>\n<font color=\"#FFFFFF\">و معلم موسیقیه</font>"
  },
  {
    "id": 10,
    "source": "<font color=\"#FFFF00\">Theodor Henri Kröger.</font>",
    "text": "<font color=\"#FFFF00\">تئودور هنری کروگر</font>"
  },
  {
    "id": 11,
    "source": "<font color=\"#FFFF00\">Der Bobbele des Golfsports.</font>",
    "text": "<font color=\"#FFFF00\">اسطوره دنیای گلف</font>"
  },
  {
    "id": 12,
    "source": "<font color=\"#00FFFF\">Ich weiß nicht,</font>\n<font color=\"#00FFFF\">wovon du sprichst, Andi.</font>",
    "text": "<font color=\"#00FFFF\">نمی‌دونم</font>\n<font color=\"#00FFFF\">داری از چی حرف می‌زنی، اندی</font>"
  },
  {
    "id": 13,
    "source": "<font color=\"#FFFF00\">Hast du lieber für dich behalten,</font>\n<font color=\"#FFFF00\">was?</font>",
    "text": "<font color=\"#FFFF00\">ترجیح دادی پیش خودت نگهش داری</font>\n<font color=\"#FFFF00\">آره؟</font>"
  },
  {
    "id": 14,
    "source": "<font color=\"#00FFFF\">Wolltest du irgendetwas Bestimmtes?</font>\n<font color=\"#FFFF00\">Du.</font>",
    "text": "<font color=\"#00FFFF\">چیز خاصی می‌خواستی؟</font>\n<font color=\"#FFFF00\">خودت</font>"
  },
  {
    "id": 15,
    "source": "<font color=\"#FFFF00\">Es geht nicht um mich,</font>\n<font color=\"#FFFF00\">sondern um Rocco.</font>",
    "text": "<font color=\"#FFFF00\">قضیه من نیستم</font>\n<font color=\"#FFFF00\">قضیه روکوئه</font>"
  },
  {
    "id": 16,
    "source": "<font color=\"#FFFF00\">Der Junge ist ein Golftalent,</font>\n<font color=\"#FFFF00\">das spüre ich.</font>",
    "text": "<font color=\"#FFFF00\">این پسر استعداد گلفه</font>\n<font color=\"#FFFF00\">حسش می‌کنم</font>"
  },
  {
    "id": 17,
    "source": "<font color=\"#FFFF00\">Dem fehlt nur noch</font>\n<font color=\"#FFFF00\">das gewisse Feingefühl.</font>",
    "text": "<font color=\"#FFFF00\">فقط اون ظرافتِ لازم رو</font>\n<font color=\"#FFFF00\">کم داره</font>"
  },
  {
    "id": 18,
    "source": "<font color=\"#FFFF00\">Und das kannst</font>\n<font color=\"#FFFF00\">du ihm beibringen, Theo.</font>",
    "text": "<font color=\"#FFFF00\">و تو می‌تونی</font>\n<font color=\"#FFFF00\">اون رو بهش یاد بدی، تئو</font>"
  },
  {
    "id": 19,
    "source": "<font color=\"#FFFF00\">Du kannst dich verstecken, aber du</font>\n<font color=\"#FFFF00\">kannst nicht ändern, wer du bist.</font>",
    "text": "<font color=\"#FFFF00\">می‌تونی قایم بشی، ولی</font>\n<font color=\"#FFFF00\">نمی‌تونی عوض کنی که کی هستی</font>"
  },
  {
    "id": 20,
    "source": "<font color=\"#FFFF00\">Theodor Henri Kröger!</font>",
    "text": "<font color=\"#FFFF00\">تئودور هنری کروگر</font>"
  },
  {
    "id": 21,
    "source": "<font color=\"#FFFFFF\">* Nachrichtenton *</font>",
    "text": "<font color=\"#FFFFFF\">* صدای پیام *</font>"
  },
  {
    "id": 22,
    "source": "<font color=\"#FFFFFF\">Fridays?</font>",
    "text": "<font color=\"#FFFFFF\">فرایدیز؟</font>"
  },
  {
    "id": 23,
    "source": "<font color=\"#FFFFFF\">Was haben die geschrieben?</font>\n<font color=\"#FFFFFF\">- \"Wir sind zu dem Schluss gekommen,</font>",
    "text": "<font color=\"#FFFFFF\">چی نوشتن؟</font>\n<font color=\"#FFFFFF\">- «ما به این نتیجه رسیدیم که</font>"
  },
  {
    "id": 24,
    "source": "<font color=\"#FFFFFF\">dass wir euch</font>\n<font color=\"#FFFFFF\">nicht unterstützen können,</font>",
    "text": "<font color=\"#FFFFFF\">نمی‌تونیم از شما</font>\n<font color=\"#FFFFFF\">حمایت کنیم</font>"
  },
  {
    "id": 25,
    "source": "<font color=\"#FFFFFF\">da euer Anliegen ...</font>\n<font color=\"#FFFFFF\">zu wenig substanziell ist.</font>",
    "text": "<font color=\"#FFFFFF\">چون درخواست شما</font>\n<font color=\"#FFFFFF\">محتوای کافی نداره»</font>"
  }
]

[
  {
    "id": 1,
    "source": "<font color=\"#00FFFF\">Der Ball muss in einer Linie</font>\n<font color=\"#00FFFF\">mit deiner linken Ferse liegen,</font>",
    "text": "<font color=\"#00FFFF\">توپ باید دقیقاً در یک راستا</font>\n<font color=\"#00FFFF\">با پاشنه پای چپت باشه</font>"
  },
  {
    "id": 2,
    "source": "<font color=\"#00FFFF\">nicht in der Mitte.</font>",
    "text": "<font color=\"#00FFFF\">نه وسط</font>"
  },
  {
    "id": 3,
    "source": "<font color=\"#FFFFFF\">* Ruhige Musik *</font>",
    "text": "<font color=\"#FFFFFF\">* موسیقی آرام *</font>"
  },
  {
    "id": 4,
    "source": "<font color=\"#FFFFFF\">* Schelmische Musik *</font>",
    "text": "<font color=\"#FFFFFF\">* موسیقی شیطنت‌آمیز *</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#00FF00\">Los!</font>",
    "text": "<font color=\"#00FF00\">بزن بریم</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#00FF00\">Da lang.</font>",
    "text": "<font color=\"#00FF00\">از اون طرف</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#FFFFFF\">Ich kann nicht mehr, Mama.</font>",
    "text": "<font color=\"#FFFFFF\">دیگه نمی‌تونم مامان</font>"
  },
  {
    "id": 8,
    "source": "<font color=\"#00FF00\">Das muss irgendwo hier sein.</font>",
    "text": "<font color=\"#00FF00\">باید همین دور و برا باشه</font>"
  },
  {
    "id": 9,
    "source": "<font color=\"#00FF00\">Sie stecken</font>\n<font color=\"#00FF00\">doch Fähnchen in die Löcher.</font>",
    "text": "<font color=\"#00FF00\">مگه تو سوراخ‌ها</font>\n<font color=\"#00FF00\">پرچم نمی‌ذارن</font>"
  },
  {
    "id": 10,
    "source": "<font color=\"#FFFFFF\">Vielleicht sind die nachts zu?</font>\n<font color=\"#00FF00\">Mist.</font>",
    "text": "<font color=\"#FFFFFF\">شاید شبا می‌بندنشون؟</font>\n<font color=\"#00FF00\">لعنتی</font>"
  },
  {
    "id": 11,
    "source": "<font color=\"#FFFFFF\">Da.</font>\n<font color=\"#00FF00\">Los.</font>",
    "text": "<font color=\"#FFFFFF\">اونجا</font>\n<font color=\"#00FF00\">بدو</font>"
  },
  {
    "id": 12,
    "source": "<font color=\"#FFFFFF\">Was ist denn das?</font>\n<font color=\"#00FF00\">Reste.</font>",
    "text": "<font color=\"#FFFFFF\">این دیگه چیه؟</font>\n<font color=\"#00FF00\">پس‌مونده‌ها</font>"
  },
  {
    "id": 13,
    "source": "<font color=\"#00FF00\">Schimmliger Kohl, faule Eier,</font>",
    "text": "<font color=\"#00FF00\">کلم کپک‌زده، تخم‌مرغ گندیده</font>"
  },
  {
    "id": 14,
    "source": "<font color=\"#00FF00\">gammliges Hack,</font>\n<font color=\"#00FF00\">gegorene Muttermilch.</font>",
    "text": "<font color=\"#00FF00\">چرخ‌کرده فاسد</font>\n<font color=\"#00FF00\">شیر مادر ترشیده</font>"
  },
  {
    "id": 15,
    "source": "<font color=\"#FFFFFF\">Stinkt aber wie Scheiße.</font>\n<font color=\"#00FF00\">Disruption muss wehtun.</font>",
    "text": "<font color=\"#FFFFFF\">ولی بوی گند میده</font>\n<font color=\"#00FF00\">تحول باید دردناک باشه</font>"
  },
  {
    "id": 16,
    "source": "<font color=\"#00FF00\">Wer will?</font>",
    "text": "<font color=\"#00FF00\">کی می‌خواد؟</font>"
  },
  {
    "id": 17,
    "source": "<font color=\"#FFFFFF\">SWOT-Analyse, my ass.</font>",
    "text": "<font color=\"#FFFFFF\">تحلیل SWOT رو بی‌خیال</font>"
  },
  {
    "id": 18,
    "source": "<font color=\"#FFFFFF\">* Spannungsvolle Musik *</font>",
    "text": "<font color=\"#FFFFFF\">* موسیقی پرتعلیق *</font>"
  },
  {
    "id": 19,
    "source": "<font color=\"#00FF00\">Warte. Ich habe was Besseres.</font>",
    "text": "<font color=\"#00FF00\">صبر کن، یه چیز بهتر دارم</font>"
  },
  {
    "id": 20,
    "source": "<font color=\"#00FF00\">Folie.</font>",
    "text": "<font color=\"#00FF00\">پلاستیک</font>"
  },
  {
    "id": 21,
    "source": "<font color=\"#FFFFFF\">Ist das nicht auch</font>\n<font color=\"#FFFFFF\">schlecht für die Umwelt?</font>",
    "text": "<font color=\"#FFFFFF\">اینم برای محیط زیست</font>\n<font color=\"#FFFFFF\">بد نیست؟</font>"
  },
  {
    "id": 22,
    "source": "<font color=\"#00FF00\">Wo gehobelt wird,</font>\n<font color=\"#00FF00\">fallen auch Späne.</font>",
    "text": "<font color=\"#00FF00\">هر کاری هزینه‌ای داره</font>\n<font color=\"#00FF00\">باید یه چیزی رو فدا کرد</font>"
  },
  {
    "id": 23,
    "source": "<font color=\"#FFFFFF\">* Treibende Musik *</font>",
    "text": "<font color=\"#FFFFFF\">* موسیقی پرانرژی *</font>"
  },
  {
    "id": 24,
    "source": "<font color=\"#FFFFFF\">* Scheppern *</font>",
    "text": "<font color=\"#FFFFFF\">* صدای خرت‌وپرت *</font>"
  },
  {
    "id": 25,
    "source": "<font color=\"#FFFFFF\">* Ein Hund bellt. *</font>",
    "text": "<font color=\"#FFFFFF\">* صدای پارس سگ *</font>"
  }
]

[
  {
    "id": 1,
    "source": "<font color=\"#FFFFFF\">Meine lieben Damen und Herren.</font>",
    "text": "<font color=\"#FFFFFF\">خانم‌ها و آقایان عزیز</font>"
  },
  {
    "id": 2,
    "source": "<font color=\"#FFFFFF\">Ich bin Jochen Reimers, CEO und</font>\n<font color=\"#FFFFFF\">Chairman der \"Der Golfplatz-Gruppe\".</font>",
    "text": "<font color=\"#FFFFFF\">من یوخن رایمرس هستم، مدیرعامل و</font>\n<font color=\"#FFFFFF\">رئیس هیئت مدیره «گروه زمین‌های گلف»</font>"
  },
  {
    "id": 3,
    "source": "<font color=\"#FFFFFF\">Ich heiße Sie willkommen auf</font>\n<font color=\"#FFFFFF\">dem Gelände des Clubs Schönefelde,</font>",
    "text": "<font color=\"#FFFFFF\">به شما در محوطه باشگاه شونه‌فلده خوش‌آمد می‌گویم،</font>\n<font color=\"#FFFFFF\">جایی که...</font>"
  },
  {
    "id": 4,
    "source": "<font color=\"#FFFFFF\">der als \"Der Golfplatz Schönefelde\"</font>\n<font color=\"#FFFFFF\">bald in neuem Glanz erstrahlen wird.</font>",
    "text": "<font color=\"#FFFFFF\">که به زودی با نام «زمین گلف شونه‌فلده»</font>\n<font color=\"#FFFFFF\">در شکوهی تازه خواهد درخشید</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#FFFFFF\">Die Einnahmen des heutigen Tages</font>",
    "text": "<font color=\"#FFFFFF\">درآمدهای امروز</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#FFFFFF\">werden direkt an wohltätige</font>\n<font color=\"#FFFFFF\">Golfprojekte in Südafrika gespendet.</font>",
    "text": "<font color=\"#FFFFFF\">مستقیماً به پروژه‌های خیریه گلف</font>\n<font color=\"#FFFFFF\">در آفریقای جنوبی اهدا خواهد شد</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#FF00FF\">Super. Ganz toll.</font>",
    "text": "<font color=\"#FF00FF\">عالیه. خیلی هم عالی</font>"
  },
  {
    "id": 8,
    "source": "<font color=\"#FFFFFF\">In den letzten Wochen wurde viel</font>\n<font color=\"#FFFFFF\">über unser Vorhaben berichtet.</font>",
    "text": "<font color=\"#FFFFFF\">در هفته‌های اخیر گزارش‌های زیادی</font>\n<font color=\"#FFFFFF\">درباره پروژه ما منتشر شده</font>"
  },
  {
    "id": 9,
    "source": "<font color=\"#FFFFFF\">Es gab Beiträge in der lokalen</font>\n<font color=\"#FFFFFF\">und regionalen Presse.</font>",
    "text": "<font color=\"#FFFFFF\">مطالبی در مطبوعات محلی</font>\n<font color=\"#FFFFFF\">و منطقه‌ای چاپ شده</font>"
  },
  {
    "id": 10,
    "source": "<font color=\"#FFFF00\">Mausi, was machst du denn hier?</font>\n<font color=\"#FF00FF\">Was denn wohl?</font>",
    "text": "<font color=\"#FFFF00\">موشی، تو اینجا چیکار می‌کنی؟</font>\n<font color=\"#FF00FF\">به نظرت چیکار می‌کنم؟</font>"
  },
  {
    "id": 11,
    "source": "<font color=\"#FFFF00\">So einen Fummel</font>\n<font color=\"#FFFF00\">haben nur Spieler an.</font>",
    "text": "<font color=\"#FFFF00\">فقط بازیکنا</font>\n<font color=\"#FFFF00\">این‌جور لباسا رو می‌پوشن</font>"
  },
  {
    "id": 12,
    "source": "<font color=\"#FF00FF\">Genau,</font>\n<font color=\"#FF00FF\">ich habe mich auch angemeldet.</font>",
    "text": "<font color=\"#FF00FF\">دقیقاً،</font>\n<font color=\"#FF00FF\">منم ثبت‌نام کردم</font>"
  },
  {
    "id": 13,
    "source": "<font color=\"#FFFFFF\">...Sie sind heute gekommen...</font>\n<font color=\"#FFFF00\">Was hast du?</font>",
    "text": "<font color=\"#FFFFFF\">...شما امروز اومدید...</font>\n<font color=\"#FFFF00\">چی کار کردی؟</font>"
  },
  {
    "id": 14,
    "source": "<font color=\"#FFFF00\">Tracy, Rocco ist ein Nervenbündel.</font>",
    "text": "<font color=\"#FFFF00\">تریسی، روکو الان یه تیکه اعصابه</font>"
  },
  {
    "id": 15,
    "source": "<font color=\"#FFFF00\">Was passiert, wenn der gegen</font>\n<font color=\"#FFFF00\">seine eigene Mutter antreten muss?</font>",
    "text": "<font color=\"#FFFF00\">اگه مجبور بشه جلوی</font>\n<font color=\"#FFFF00\">مادر خودش بازی کنه چی؟</font>"
  },
  {
    "id": 16,
    "source": "<font color=\"#FFFF00\">Das kannst du ihm nicht antun.</font>\n<font color=\"#FF00FF\">Und ob.</font>",
    "text": "<font color=\"#FFFF00\">نمی‌تونی این کارو باهاش بکنی</font>\n<font color=\"#FF00FF\">اتفاقاً خیلی هم می‌تونم</font>"
  },
  {
    "id": 17,
    "source": "<font color=\"#FFFF00\">Setzen wir sein Talent</font>\n<font color=\"#FFFF00\">nicht aufs Spiel.</font>",
    "text": "<font color=\"#FFFF00\">استعدادش رو</font>\n<font color=\"#FFFF00\">به خطر نندازیم</font>"
  },
  {
    "id": 18,
    "source": "<font color=\"#FFFF00\">Wir müssen ihn unterstützen.</font>",
    "text": "<font color=\"#FFFF00\">باید ازش حمایت کنیم</font>"
  },
  {
    "id": 19,
    "source": "<font color=\"#FF00FF\">Du unterstützt</font>\n<font color=\"#FF00FF\">nur seine Mitgliedschaft.</font>",
    "text": "<font color=\"#FF00FF\">تو فقط داری از</font>\n<font color=\"#FF00FF\">عضویتش حمایت می‌کنی</font>"
  },
  {
    "id": 20,
    "source": "<font color=\"#FF00FF\">Damit du auch reinkannst.</font>\n<font color=\"#FFFF00\">Das ist...</font>",
    "text": "<font color=\"#FF00FF\">که خودتم بتونی بیای تو</font>\n<font color=\"#FFFF00\">این...</font>"
  },
  {
    "id": 21,
    "source": "<font color=\"#FFFF00\">Ich trainiere jeden Tag,</font>\n<font color=\"#FFFF00\">damit aus dem ein Großer wird.</font>",
    "text": "<font color=\"#FFFF00\">من هر روز تمرین می‌کنم</font>\n<font color=\"#FFFF00\">تا اون یه آدم بزرگ بشه</font>"
  },
  {
    "id": 22,
    "source": "<font color=\"#FFFFFF\">Hey, pst!</font>",
    "text": "<font color=\"#FFFFFF\">هی، هیس!</font>"
  },
  {
    "id": 23,
    "source": "<font color=\"#FF00FF\">Wenn er ein Großer werden will,</font>\n<font color=\"#FF00FF\">muss er mit Konkurrenz klarkommen.</font>",
    "text": "<font color=\"#FF00FF\">اگه می‌خواد آدم بزرگی بشه،</font>\n<font color=\"#FF00FF\">باید بتونه با رقیب کنار بیاد</font>"
  },
  {
    "id": 24,
    "source": "<font color=\"#FFFFFF\">* Jubel *</font>\n<font color=\"#FF00FF\">Ganz toll.</font>",
    "text": "<font color=\"#FFFFFF\">* تشویق *</font>\n<font color=\"#FF00FF\">خیلی هم عالی</font>"
  },
  {
    "id": 25,
    "source": "<font color=\"#FF00FF\">Ganz toll.</font>",
    "text": "<font color=\"#FF00FF\">خیلی هم عالی</font>"
  }
]

[
  {
    "id": 1,
    "source": "<font color=\"#FFFFFF\">...und weil wir den Weg</font>\n<font color=\"#FFFFFF\">des visionären Nocheigentümers</font>",
    "text": "<font color=\"#FFFFFF\">...و چون می‌خواهیم راه</font>\n<font color=\"#FFFFFF\">مالک فعلی و آینده‌نگر</font>"
  },
  {
    "id": 2,
    "source": "<font color=\"#FFFFFF\">Gert Behnke fortführen wollen.</font>",
    "text": "<font color=\"#FFFFFF\">یعنی گرت بنکه را ادامه دهیم</font>"
  },
  {
    "id": 3,
    "source": "<font color=\"#FFFFFF\">Gert hat sein Leben</font>\n<font color=\"#FFFFFF\">dem Golfsport verschrieben.</font>",
    "text": "<font color=\"#FFFFFF\">گرت تمام زندگی‌اش را</font>\n<font color=\"#FFFFFF\">وقف گلف کرده بود</font>"
  },
  {
    "id": 4,
    "source": "<font color=\"#FFFFFF\">Er hat alles auf dem Platz gelassen.</font>\n<font color=\"#FFFFFF\">Sogar seine Gesundheit.</font>",
    "text": "<font color=\"#FFFFFF\">او همه چیزش را در زمین گذاشت</font>\n<font color=\"#FFFFFF\">حتی سلامتی‌اش را</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#FFFFFF\">Ich sollte eine Bemerkung</font>\n<font color=\"#FFFFFF\">zu einem Brief machen,</font>",
    "text": "<font color=\"#FFFFFF\">باید در مورد نامه‌ای</font>\n<font color=\"#FFFFFF\">که امروز به دستمان رسیده</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#FFFFFF\">den wir heute erhalten haben</font>\n<font color=\"#FFFFFF\">von Umweltaktivsten.</font>",
    "text": "<font color=\"#FFFFFF\">از طرف فعالان محیط زیست</font>\n<font color=\"#FFFFFF\">نکته‌ای را بگویم</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#FFFFFF\">Anonym natürlich.</font>\n<font color=\"#FFFF00\">(mit Akzent) Diese Feiglinge.</font>",
    "text": "<font color=\"#FFFFFF\">البته که ناشناس</font>\n<font color=\"#FFFF00\">این بزدل‌ها</font>"
  },
  {
    "id": 8,
    "source": "<font color=\"#FFFF00\">Diese Flitzpiepen.</font>",
    "text": "<font color=\"#FFFF00\">این مسخره‌های بی‌عرضه</font>"
  },
  {
    "id": 9,
    "source": "<font color=\"#FFFFFF\">Sie haben damit gedroht, die</font>\n<font color=\"#FFFFFF\">Erweiterung verhindern zu wollen.</font>",
    "text": "<font color=\"#FFFFFF\">تهدید کردن که می‌خوان</font>\n<font color=\"#FFFFFF\">جلوی توسعه رو بگیرن</font>"
  },
  {
    "id": 10,
    "source": "<font color=\"#FFFFFF\">Den jämmerlichen</font>\n<font color=\"#FFFFFF\">Möchtegern-Terroristen</font>",
    "text": "<font color=\"#FFFFFF\">به این تروریست‌های</font>\n<font color=\"#FFFFFF\">آفتابه-دزدِ بدبخت</font>"
  },
  {
    "id": 11,
    "source": "<font color=\"#FFFFFF\">wollen wir mit dem Turnier zeigen,</font>",
    "text": "<font color=\"#FFFFFF\">می‌خوایم با این مسابقات نشون بدیم</font>"
  },
  {
    "id": 12,
    "source": "<font color=\"#FFFFFF\">dass die Bürger aus Schönefelde,</font>\n<font color=\"#FFFFFF\">Sie alle, hinter uns sind.</font>",
    "text": "<font color=\"#FFFFFF\">که شهروندان شونفلد</font>\n<font color=\"#FFFFFF\">همه‌تون، پشت ما هستید</font>"
  },
  {
    "id": 13,
    "source": "<font color=\"#FFFFFF\">In diesem Sinne</font>\n<font color=\"#FFFFFF\">möchte ich das Turnier eröffnen.</font>",
    "text": "<font color=\"#FFFFFF\">با این اوصاف</font>\n<font color=\"#FFFFFF\">می‌خوام مسابقات رو افتتاح کنم</font>"
  },
  {
    "id": 14,
    "source": "<font color=\"#FFFFFF\">Bravo!</font>",
    "text": "<font color=\"#FFFFFF\">آفرین</font>"
  },
  {
    "id": 15,
    "source": "<font color=\"#FFFFFF\">* Plätschern *</font>\n<font color=\"#FFFFFF\">Jawohl!</font>",
    "text": "<font color=\"#FFFFFF\">* صدای آب *</font>\n<font color=\"#FFFFFF\">دمتون گرم</font>"
  },
  {
    "id": 16,
    "source": "<font color=\"#FFFFFF\">Ja.</font>",
    "text": "<font color=\"#FFFFFF\">آره</font>"
  },
  {
    "id": 17,
    "source": "<font color=\"#FFFFFF\">Hat es hier gestern geregnet?</font>",
    "text": "<font color=\"#FFFFFF\">دیروز اینجا بارون اومده؟</font>"
  },
  {
    "id": 18,
    "source": "<font color=\"#FFFFFF\">* Alle lachen. *</font>",
    "text": "<font color=\"#FFFFFF\">* همه می‌خندند *</font>"
  },
  {
    "id": 19,
    "source": "<font color=\"#FFFFFF\">Oh Mann, ey.</font>",
    "text": "<font color=\"#FFFFFF\">ای بابا، ول کن</font>"
  },
  {
    "id": 20,
    "source": "<font color=\"#FFFFFF\">So, wir kommen jetzt zum ersten Teil</font>\n<font color=\"#FFFFFF\">der Vorrunde, dem Abschlag.</font>",
    "text": "<font color=\"#FFFFFF\">خب، حالا می‌رسیم به بخش اول</font>\n<font color=\"#FFFFFF\">مقدماتی، یعنی ضربه شروع</font>"
  },
  {
    "id": 21,
    "source": "<font color=\"#FFFFFF\">Hier trennt</font>\n<font color=\"#FFFFFF\">sich die Spreu vom Weizen.</font>",
    "text": "<font color=\"#FFFFFF\">اینجا جاییه که</font>\n<font color=\"#FFFFFF\">حساب کار دست همه میاد</font>"
  },
  {
    "id": 22,
    "source": "<font color=\"#FFFFFF\">Unsere ersten Spieler sind:</font>",
    "text": "<font color=\"#FFFFFF\">اولین بازیکن‌های ما اینا هستن:</font>"
  },
  {
    "id": 23,
    "source": "<font color=\"#FFFFFF\">Michael Latzek.</font>\n<font color=\"#FFFFFF\">* Jubel *</font>",
    "text": "<font color=\"#FFFFFF\">میشائیل لاتسک</font>\n<font color=\"#FFFFFF\">* تشویق *</font>"
  },
  {
    "id": 24,
    "source": "<font color=\"#FFFFFF\">Tracy Knuppe.</font>\n<font color=\"#FFFFFF\">* Jubel *</font>",
    "text": "<font color=\"#FFFFFF\">تریسی کنوپه</font>\n<font color=\"#FFFFFF\">* تشویق *</font>"
  },
  {
    "id": 25,
    "source": "<font color=\"#FFFFFF\">Und Rocco ...</font>",
    "text": "<font color=\"#FFFFFF\">و روکو...</font>"
  }
]

[
  {
    "id": 1,
    "source": "<font color=\"#FFFFFF\">Denn er ist</font>\n<font color=\"#FFFFFF\">mit Rocco Knüppé gleichauf.</font>",
    "text": "<font color=\"#FFFFFF\">چون اون الان</font>\n<font color=\"#FFFFFF\">با روکو کنوپه مساوی شده</font>"
  },
  {
    "id": 2,
    "source": "<font color=\"#FFFFFF\">Fuck! Warum?</font>",
    "text": "<font color=\"#FFFFFF\">لعنتی! چرا؟</font>"
  },
  {
    "id": 3,
    "source": "<font color=\"#FFFFFF\">Hey, hey, hey! Henri Fore!</font>",
    "text": "<font color=\"#FFFFFF\">هی، هی، هی! هنری، مراقب باش</font>"
  },
  {
    "id": 4,
    "source": "<font color=\"#FFFFFF\">Wahnsinn, was für eine Dramatik</font>\n<font color=\"#FFFFFF\">hier am Vorrundentag.</font>",
    "text": "<font color=\"#FFFFFF\">عجب چیزی، چه هیجانی</font>\n<font color=\"#FFFFFF\">توی این روز مسابقات مقدماتی</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#FFFFFF\">Und jetzt ... liegt alles</font>\n<font color=\"#FFFFFF\">in der Hand von Rocco Knüppé.</font>",
    "text": "<font color=\"#FFFFFF\">و حالا... همه چیز</font>\n<font color=\"#FFFFFF\">دست روکو کنوپه‌ست</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#FFFFFF\">Wenn er einlocht, steht er</font>\n<font color=\"#FFFFFF\">mit seiner eigenen Mutter...</font>",
    "text": "<font color=\"#FFFFFF\">اگه توپ رو بندازه تو سوراخ،</font>\n<font color=\"#FFFFFF\">با مادر خودش...</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#FFFF00\">Halt die Klappe.</font>\n<font color=\"#FFFFFF\">Mann.</font>",
    "text": "<font color=\"#FFFF00\">خفه شو دیگه</font>\n<font color=\"#FFFFFF\">مرد</font>"
  },
  {
    "id": 8,
    "source": "<font color=\"#FFFF00\">Bist nicht im Fernsehen. Mon Dieu.</font>\n<font color=\"#FFFFFF\">Sag mal...</font>",
    "text": "<font color=\"#FFFF00\">تلویزیون که نیستی، خدای من</font>\n<font color=\"#FFFFFF\">بگو ببینم...</font>"
  },
  {
    "id": 9,
    "source": "<font color=\"#FFFFFF\">Wird jetzt Rocco Knüppé es schaffen,</font>",
    "text": "<font color=\"#FFFFFF\">آیا روکو کنوپه موفق می‌شه،</font>"
  },
  {
    "id": 10,
    "source": "<font color=\"#FFFFFF\">das letzte Ticket</font>\n<font color=\"#FFFFFF\">fürs Turnier zu ziehen?</font>",
    "text": "<font color=\"#FFFFFF\">آخرین بلیط</font>\n<font color=\"#FFFFFF\">برای تورنمنت رو بگیره؟</font>"
  },
  {
    "id": 11,
    "source": "<font color=\"#FFFFFF\">* Spannungsvolle Musik *</font>",
    "text": "<font color=\"#FFFFFF\">* موسیقی پرهیجان *</font>"
  },
  {
    "id": 12,
    "source": "<font color=\"#FFFFFF\">* Jubel *</font>",
    "text": "<font color=\"#FFFFFF\">* صدای تشویق *</font>"
  },
  {
    "id": 13,
    "source": "<font color=\"#FFFFFF\">Wahnsinn!</font>",
    "text": "<font color=\"#FFFFFF\">ایول!</font>"
  },
  {
    "id": 14,
    "source": "<font color=\"#FFFFFF\">Rocco!</font>",
    "text": "<font color=\"#FFFFFF\">روکو!</font>"
  },
  {
    "id": 15,
    "source": "<font color=\"#FFFF00\">Rocci!</font>",
    "text": "<font color=\"#FFFF00\">روکی!</font>"
  },
  {
    "id": 16,
    "source": "<font color=\"#FFFFFF\">Wir haben</font>\n<font color=\"#FFFFFF\">die Finalisten für Sonntag.</font>",
    "text": "<font color=\"#FFFFFF\">ما فینالیست‌های</font>\n<font color=\"#FFFFFF\">یکشنبه رو داریم</font>"
  },
  {
    "id": 17,
    "source": "<font color=\"#FFFFFF\">Es sind Judith Reimers, Tracy Knuppe</font>\n<font color=\"#FFFFFF\">und der fantastische Rocco.</font>",
    "text": "<font color=\"#FFFFFF\">اونا جودیت رایمرز، تریسی کنوپه</font>\n<font color=\"#FFFFFF\">و روکوی فوق‌العاده هستن</font>"
  },
  {
    "id": 18,
    "source": "<font color=\"#FFFFFF\">Wahnsinn!</font>",
    "text": "<font color=\"#FFFFFF\">محشره!</font>"
  },
  {
    "id": 19,
    "source": "<font color=\"#FFFFFF\">* Heroische Musik *</font>",
    "text": "<font color=\"#FFFFFF\">* موسیقی حماسی *</font>"
  },
  {
    "id": 20,
    "source": "<font color=\"#FFFFFF\">Der dachte, dass das Regen war.</font>\n<font color=\"#00FF00\">Weil er dumm ist.</font>",
    "text": "<font color=\"#FFFFFF\">فکر کرد بارون بوده</font>\n<font color=\"#00FF00\">چون احمقه</font>"
  },
  {
    "id": 21,
    "source": "<font color=\"#FFFFFF\">Du würdest auch nicht denken,</font>\n<font color=\"#FFFFFF\">dass irgendwer reingepisst hat.</font>",
    "text": "<font color=\"#FFFFFF\">تو هم فکر نمی‌کردی</font>\n<font color=\"#FFFFFF\">که کسی توش جیش کرده باشه</font>"
  },
  {
    "id": 22,
    "source": "<font color=\"#00FF00\">Um den Bau zu stoppen, müssen wir</font>\n<font color=\"#00FF00\">größere Geschütze auffahren.</font>",
    "text": "<font color=\"#00FF00\">برای متوقف کردن ساخت‌وساز، باید</font>\n<font color=\"#00FF00\">از روش‌های جدی‌تری استفاده کنیم</font>"
  },
  {
    "id": 23,
    "source": "<font color=\"#FFFFFF\">I.</font>\n<font color=\"#00FF00\">So war das doch nicht gemeint.</font>",
    "text": "<font color=\"#FFFFFF\">من</font>\n<font color=\"#00FF00\">منظورم این نبود</font>"
  },
  {
    "id": 24,
    "source": "<font color=\"#00FF00\">Wobei das auch ein Statement wäre,</font>",
    "text": "<font color=\"#00FF00\">هرچند این خودش یه جور بیانیه بود،</font>"
  },
  {
    "id": 25,
    "source": "<font color=\"#00FF00\">wenn da überall</font>\n<font color=\"#00FF00\">kleine Häufchen rausgucken.</font>",
    "text": "<font color=\"#00FF00\">اگه همه‌جا</font>\n<font color=\"#00FF00\">تپه‌های کوچیک بزنه بیرون</font>"
  }
]

[
  {
    "id": 1,
    "source": "<font color=\"#FFFFFF\">Mama?</font>\n<font color=\"#00FF00\">Ja?</font>",
    "text": "<font color=\"#FFFFFF\">مامان؟</font>\n<font color=\"#00FF00\">بله؟</font>"
  },
  {
    "id": 2,
    "source": "<font color=\"#FFFFFF\">Wir müssen</font>\n<font color=\"#FFFFFF\">mal kurz unter vier Augen reden.</font>",
    "text": "<font color=\"#FFFFFF\">باید یه لحظه</font>\n<font color=\"#FFFFFF\">خصوصی با هم حرف بزنیم</font>"
  },
  {
    "id": 3,
    "source": "<font color=\"#00FF00\">Also, das war jetzt nur ein Scherz.</font>\n<font color=\"#FFFFFF\">Kannst du rausgehen?</font>",
    "text": "<font color=\"#00FF00\">خب، اون فقط یه شوخی بود</font>\n<font color=\"#FFFFFF\">میشه بری بیرون؟</font>"
  },
  {
    "id": 4,
    "source": "<font color=\"#00FF00\">Ja, klar. Also, ja...</font>",
    "text": "<font color=\"#00FF00\">آره، حتماً. خب، آره...</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#FFFFFF\">(Zoe) Tür zu.</font>",
    "text": "<font color=\"#FFFFFF\">(زوئی) درو ببند</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#00FF00\">Ich habe es.</font>\n<font color=\"#00FF00\">Ich weiß, was wir machen.</font>",
    "text": "<font color=\"#00FF00\">فهمیدم</font>\n<font color=\"#00FF00\">می‌دونم باید چیکار کنیم</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#FFFFFF\">Wir müssen unsere Zusammenarbeit</font>\n<font color=\"#FFFFFF\">mit dir beenden.</font>",
    "text": "<font color=\"#FFFFFF\">ما باید همکاری‌مون</font>\n<font color=\"#FFFFFF\">با تو رو تموم کنیم</font>"
  },
  {
    "id": 8,
    "source": "<font color=\"#00FF00\">Was? </font><font color=\"#FFFFFF\">Es gibt</font>\n<font color=\"#FFFFFF\">kein richtiges Leben im falschen.</font>",
    "text": "<font color=\"#00FF00\">چی؟ </font><font color=\"#FFFFFF\">توی یه زندگیِ غلط،</font>\n<font color=\"#FFFFFF\">هیچ زندگیِ درستی وجود نداره</font>"
  },
  {
    "id": 9,
    "source": "<font color=\"#FFFFFF\">Wir konzentrieren uns</font>\n<font color=\"#FFFFFF\">auf die Schule,</font>",
    "text": "<font color=\"#FFFFFF\">ما تمرکزمون رو می‌ذاریم</font>\n<font color=\"#FFFFFF\">روی درس و مدرسه</font>"
  },
  {
    "id": 10,
    "source": "<font color=\"#FFFFFF\">werden Anwältinnen</font>\n<font color=\"#FFFFFF\">oder Ministerinnen.</font>",
    "text": "<font color=\"#FFFFFF\">وکیل می‌شیم</font>\n<font color=\"#FFFFFF\">یا وزیر</font>"
  },
  {
    "id": 11,
    "source": "<font color=\"#FFFFFF\">Wir wollen das System</font>\n<font color=\"#FFFFFF\">von innen bekämpfen.</font>",
    "text": "<font color=\"#FFFFFF\">می‌خوایم با سیستم</font>\n<font color=\"#FFFFFF\">از درون بجنگیم</font>"
  },
  {
    "id": 12,
    "source": "<font color=\"#FFFFFF\">Nicht</font>\n<font color=\"#FFFFFF\">in irgendwelche Löcher pinkeln.</font>",
    "text": "<font color=\"#FFFFFF\">نه اینکه</font>\n<font color=\"#FFFFFF\">توی هر سوراخ‌سمبه‌ای جیش کنیم</font>"
  },
  {
    "id": 13,
    "source": "<font color=\"#00FF00\">Okay.</font>",
    "text": "<font color=\"#00FF00\">باشه</font>"
  },
  {
    "id": 14,
    "source": "<font color=\"#FFFFFF\">Los, Mama, raus.</font>",
    "text": "<font color=\"#FFFFFF\">یالا مامان، برو بیرون</font>"
  },
  {
    "id": 15,
    "source": "<font color=\"#00FFFF\">Hey, Champ.</font>",
    "text": "<font color=\"#00FFFF\">هی، قهرمان</font>"
  },
  {
    "id": 16,
    "source": "<font color=\"#00FFFF\">Alles klar?</font>",
    "text": "<font color=\"#00FFFF\">اوضاع روبه‌راهه؟</font>"
  },
  {
    "id": 17,
    "source": "<font color=\"#00FFFF\">Was ist denn los?</font>",
    "text": "<font color=\"#00FFFF\">چی شده؟</font>"
  },
  {
    "id": 18,
    "source": "<font color=\"#00FFFF\">Freust du dich</font>\n<font color=\"#00FFFF\">nicht auf das Turnier?</font>",
    "text": "<font color=\"#00FFFF\">واسه مسابقات</font>\n<font color=\"#00FFFF\">هیجان نداری؟</font>"
  },
  {
    "id": 19,
    "source": "<font color=\"#FFFFFF\">Wenn ich verliere,</font>\n<font color=\"#FFFFFF\">darf Papa nicht in den neuen Club.</font>",
    "text": "<font color=\"#FFFFFF\">اگه ببازم،</font>\n<font color=\"#FFFFFF\">بابا نمی‌تونه بره اون باشگاه جدید</font>"
  },
  {
    "id": 20,
    "source": "<font color=\"#00FFFF\">Ah, verstehe.</font>",
    "text": "<font color=\"#00FFFF\">آها، گرفتم</font>"
  },
  {
    "id": 21,
    "source": "<font color=\"#00FFFF\">Aber das Wichtigste ist,</font>\n<font color=\"#00FFFF\">dass du das für dich machst,</font>",
    "text": "<font color=\"#00FFFF\">ولی مهم‌ترین چیز اینه که</font>\n<font color=\"#00FFFF\">این کار رو واسه خودت انجام بدی</font>"
  },
  {
    "id": 22,
    "source": "<font color=\"#00FFFF\">nicht für jemand anderen,</font>\n<font color=\"#00FFFF\">auch nicht für deinen Papa.</font>",
    "text": "<font color=\"#00FFFF\">نه واسه کس دیگه‌ای،</font>\n<font color=\"#00FFFF\">حتی نه واسه بابات</font>"
  },
  {
    "id": 23,
    "source": "<font color=\"#00FFFF\">Ich war früher so besessen davon,</font>\n<font color=\"#00FFFF\">zu gewinnen,</font>",
    "text": "<font color=\"#00FFFF\">من قدیما اون‌قدر وسواسِ</font>\n<font color=\"#00FFFF\">بردن داشتم که</font>"
  },
  {
    "id": 24,
    "source": "<font color=\"#00FFFF\">dass mir das Spiel irgendwann</font>\n<font color=\"#00FFFF\">keinen Spaß mehr gemacht hat.</font>",
    "text": "<font color=\"#00FFFF\">دیگه بازی کردن</font>\n<font color=\"#00FFFF\">برام هیچ لذتی نداشت</font>"
  },
  {
    "id": 25,
    "source": "<font color=\"#00FFFF\">Und als ich einmal verloren habe,</font>",
    "text": "<font color=\"#00FFFF\">و وقتی یه بار باختم،</font>"
  }
]

[
  {
    "id": 1,
    "source": "<font color=\"#00FFFF\">sind die Pferde</font>\n<font color=\"#00FFFF\">mit mir durchgegangen.</font>",
    "text": "<font color=\"#00FFFF\">کنترل اعصابم رو</font>\n<font color=\"#00FFFF\">از دست دادم</font>"
  },
  {
    "id": 2,
    "source": "<font color=\"#00FFFF\">Danach habe ich mir geschworen, nie</font>\n<font color=\"#00FFFF\">wieder einen Golfplatz zu betreten.</font>",
    "text": "<font color=\"#00FFFF\">بعدش با خودم عهد کردم که دیگه</font>\n<font color=\"#00FFFF\">پام رو تو هیچ زمین گلفی نذارم</font>"
  },
  {
    "id": 3,
    "source": "<font color=\"#00FFFF\">Rocco, du musst Spaß haben bei dem,</font>\n<font color=\"#00FFFF\">was du machst.</font>",
    "text": "<font color=\"#00FFFF\">روکو، باید از کاری که می‌کنی</font>\n<font color=\"#00FFFF\">لذت ببری</font>"
  },
  {
    "id": 4,
    "source": "<font color=\"#00FFFF\">Sonst macht das alles</font>\n<font color=\"#00FFFF\">überhaupt keinen Sinn, oder?</font>",
    "text": "<font color=\"#00FFFF\">وگرنه کل این ماجرا</font>\n<font color=\"#00FFFF\">اصلاً معنی نداره، مگه نه؟</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#FFFFFF\">* Elektronische Musik *</font>",
    "text": "<font color=\"#FFFFFF\">* موسیقی الکترونیک *</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#FFFFFF\">♪ Schatzi, Motte.</font>",
    "text": "<font color=\"#FFFFFF\">♪ عزیزم، موته</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#FFFFFF\">Mausi, hör mir zu.</font>",
    "text": "<font color=\"#FFFFFF\">موش‌موشک، گوش بده</font>"
  },
  {
    "id": 8,
    "source": "<font color=\"#FFFFFF\">Das ist unser Schicksal.</font>",
    "text": "<font color=\"#FFFFFF\">این سرنوشت ماست</font>"
  },
  {
    "id": 9,
    "source": "<font color=\"#FFFFFF\">Du weißt, was wir tun müssen.</font>",
    "text": "<font color=\"#FFFFFF\">خودت می‌دونی باید چیکار کنیم</font>"
  },
  {
    "id": 10,
    "source": "<font color=\"#FFFFFF\">Ich weiß, was zu tun ist.</font>",
    "text": "<font color=\"#FFFFFF\">می‌دونم باید چیکار کنم</font>"
  },
  {
    "id": 11,
    "source": "<font color=\"#FFFFFF\">Zoe, Rocco.</font>",
    "text": "<font color=\"#FFFFFF\">زوئی، روکو</font>"
  },
  {
    "id": 12,
    "source": "<font color=\"#FFFFFF\">Tut, was getan werden muss.</font>",
    "text": "<font color=\"#FFFFFF\">کاری که لازمه رو انجام بدین</font>"
  },
