  },
  {
    "id": 4,
    "source": "<font color=\"#FF00FF\">Und? Ich passe trotzdem</font>\n<font color=\"#FF00FF\">nicht auf auf den.</font>",
    "text": "<font color=\"#FF00FF\">خب که چی؟ من به هر حال</font>\n<font color=\"#FF00FF\">مراقبش نیستم</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#FFFFFF\">Tracy. Sag mal...</font>",
    "text": "<font color=\"#FFFFFF\">تریسی، یه لحظه گوش کن</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#FFFFFF\">Das ist kein gewöhnliches Drama,</font>\n<font color=\"#FFFFFF\">das ist ein Familiendrama.</font>",
    "text": "<font color=\"#FFFFFF\">این یه درام معمولی نیست،</font>\n<font color=\"#FFFFFF\">این یه درام خانوادگیه</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#FF00FF\">Jetzt übertreib mal nicht.</font>\n<font color=\"#FFFFFF\">Tut mir wirklich leid, Rocco.</font>",
    "text": "<font color=\"#FF00FF\">دیگه شورش رو در نیار</font>\n<font color=\"#FFFFFF\">واقعاً متاسفم، روکو</font>"
